import type { GameState } from './types';
import generatedRemoved from './removed-nodes.json';

export const CURRENT_SAVE_VERSION = 3;

/** Story nodes removed in the shared-life revision (v3) → the nearest place that still exists. */
const MANUAL: Record<string, Record<string, string>> = {
  ch1: { bond_buttons: 'c1_hub', bond_buttons_pick: 'c1_hub', bond_retry: 'c1_hub', bond_count: 'c1_hub', bond_stop: 'c1_hub', c1_d10: 'c1_hub', c1_d12: 'c1_d13' },
  ch5: { g_clothes: 'g_war_memory' },
};
/** Lines merged or cut to reduce reading (generated by the content revision, see tools/content-revision-2026-10). */
const GENERATED = generatedRemoved as Record<string, Record<string, string>>;
export const REMOVED_NODES: Record<string, Record<string, string>> = Object.fromEntries(
  [...new Set([...Object.keys(MANUAL), ...Object.keys(GENERATED)])].map((ch) => [ch, { ...GENERATED[ch], ...MANUAL[ch] }]),
);

/**
 * Upgrade any older save to the current shape. Pure function (unit-tested).
 * v1 → v2: adds `completed`, `music`, `ambience`; folds the old 6-period day (… العشا=4, بالليل=5)
 *          into the 4-period day + night (night = 4).
 */
export function migrateSave(raw: unknown): GameState | null {
  if (!raw || typeof raw !== 'object') return null;
  let s = raw as GameState & { version?: number };
  if (typeof s.version !== 'number' || !s.node || !s.vars || !s.chapter) return null;
  if (s.version > CURRENT_SAVE_VERSION) return null;            // written by a newer build
  if (s.version === 1) {
    s = { ...s, version: 2, completed: [], slot: s.slot >= 5 ? 4 : s.slot, music: undefined, ambience: undefined };
  }
  if (s.version === 2) {
    // v2 → v3: the thread spools and clothes became real objects. Old saves start with two spools;
    // clothes states are derived from the flags they already have (see core.wardrobe).
    const remap = REMOVED_NODES[s.chapter]?.[s.node];
    s = { ...s, version: 3, flags: { thread: 2, ...s.flags }, node: remap ?? s.node, lastLine: remap ? undefined : s.lastLine };
  }
  // Any version: a node merged away in a later content revision resumes at the node that absorbed it.
  const moved = REMOVED_NODES[s.chapter]?.[s.node];
  if (moved) s = { ...s, node: moved, lastLine: undefined };
  if (s.chapter === 'ch4' && s.node.startsWith('c4_')) {
    s = { ...s, node: 's_start', scene: 'living', day: 1, slot: 0, cast: ['hoda'], visited: [], music: null, ambience: null };
  }
  if (s.visited?.includes('c2_hush_repair') && !s.flags?.c2_hush_repaired) {
    s = { ...s, flags: { ...s.flags, c2_hush_repaired: true } };
  }
  if (s.flags?.light_tonight && s.flags.bed_light !== 'on' && (s.chapter !== 'ch1' || s.day >= 2)) {
    s = { ...s, flags: { ...s.flags, bed_light: 'on' } };
  }
  if (s.chapter === 'ch2' && s.node === 'c2_day2_home') {
    const home = s.flags?.c2_plan === 'home';
    s = { ...s, node: home ? 'c2_day2_stay' : 'c2_day2_empty', scene: 'living', cast: home ? ['hoda'] : [] };
  }
  if (s.chapter === 'ch2' && s.flags?.c2_plan === 'home' && s.node === 'c2_day2_hub') {
    s = { ...s, scene: 'living', cast: ['hoda'] };
  }
  if (s.chapter === 'ch2' && ['c2_close', 'c2_end'].includes(s.node) && s.slot < 4) {
    s = { ...s, slot: 4 };
  }
  // Earlier builds recorded delivery while the player was still choosing the handover.
  if (s.chapter === 'ch5' && ['g_handover', 'final_handover', 'g_messenger', 'final_send_note'].includes(s.node)
      && ['mother', 'messenger'].includes(String(s.flags?.belongings_delivery))) {
    const flags = { ...s.flags };
    delete flags.belongings_delivery;
    s = { ...s, flags };
  }
  // Restart Chapter restores this snapshot directly, so it needs the same upgrades as the active save.
  if (s.chapterStart) s = { ...s, chapterStart: migrateSave(s.chapterStart) ?? undefined };
  return s;
}
